#!/bin/sh
# Syntax-check the Omega Lite module against an Omega checkout.
#
#   scripts/check_omega_syntax.sh /path/to/Omega
#
# This is not a firmware build: it compiles the module with a desktop compiler
# against Omega's real headers (escher, kandinsky, ion, poincare), using a
# palette.h generated by Omega's own theme engine from themes/omega_lite.json.
# It catches API misuse (wrong signatures, missing headers, typos) in seconds
# and needs no ARM toolchain. Linking for the device still requires the full
# Omega build, which this script does not replace.

set -eu

OMEGA_DIR="${1:-}"
if [ -z "$OMEGA_DIR" ]; then
    echo "usage: $0 /path/to/Omega" >&2
    exit 2
fi
REPO_DIR="$(cd "$(dirname "$0")/.." && pwd)"
BUILD_DIR="$REPO_DIR/build/omega-syntax"

mkdir -p "$BUILD_DIR/escher" "$BUILD_DIR/apps"

# Omega's theme engine turns the theme into Palette:: constants.
if [ -f "$OMEGA_DIR/themes/themes_manager.py" ]; then
    python3 "$OMEGA_DIR/themes/themes_manager.py" local omega_lite \
        "$BUILD_DIR/escher/palette.h" "$BUILD_DIR" >/dev/null
else
    echo "error: $OMEGA_DIR/themes/themes_manager.py not found" >&2
    exit 2
fi

# The real apps/i18n.h is generated from every app's translation files during
# the build. The module never uses I18n directly, so a minimal stub is enough
# to satisfy the escher headers.
cat > "$BUILD_DIR/apps/i18n.h" <<'EOF'
#ifndef APPS_I18N_H
#define APPS_I18N_H
namespace I18n {
enum class Message { Default = 0 };
}
#endif
EOF

KEYBOARD_LAYOUT="$OMEGA_DIR/ion/include/ion/keyboard/layout_B3"
if [ ! -d "$KEYBOARD_LAYOUT" ]; then
    KEYBOARD_LAYOUT="$OMEGA_DIR/ion/include/ion/keyboard/layout_B2"
fi

INCLUDES="-I$BUILD_DIR \
-I$OMEGA_DIR -I$OMEGA_DIR/apps -I$OMEGA_DIR/apps/settings -I$OMEGA_DIR/apps/shared \
-I$OMEGA_DIR/escher/include -I$OMEGA_DIR/kandinsky/include -I$OMEGA_DIR/ion/include \
-I$KEYBOARD_LAYOUT -I$OMEGA_DIR/poincare/include"

status=0
for source in "$REPO_DIR"/apps/settings/custom_colors/*.cpp; do
    if g++ -fsyntax-only -std=c++17 -Wno-unused-parameter $INCLUDES "$source"; then
        echo "OK   $(basename "$source")"
    else
        echo "FAIL $(basename "$source")"
        status=1
    fi
done

exit $status
